import json,sys,subprocess,tempfile,os,re,sqlite3,hashlib
from pathlib import Path
checks={}
def run(cmd,cwd=None):
 p=subprocess.run(cmd,cwd=cwd,capture_output=True,text=True,check=True,timeout=20);return p.stdout.strip()
checks['shell-quoting']={'unquoted':run(['/opt/local/bin/bash','-c','file="report draft.txt"; printf "<%s>\\n" $file']),'quoted':run(['/opt/local/bin/bash','-c','file="report draft.txt"; printf "<%s>\\n" "$file"'])}
with tempfile.TemporaryDirectory(prefix='edbot-cs35l-check-') as d:
 t=Path(d)
 for name,redir in [('first','>out 2>&1'),('second','2>&1 >out')]:
  proc=subprocess.run(['/opt/local/bin/bash','-c',"{ printf 'O\\n'; printf 'E\\n' >&2; } "+redir],cwd=t,capture_output=True,text=True,check=True)
  checks['redirection-'+name]={'captured_terminal_stdout':proc.stdout,'captured_terminal_stderr':proc.stderr,'out':(t/'out').read_text()}
 git=lambda *args:run(['git',*args],cwd=t)
 git('init','-q');git('config','user.email','synthetic@example.invalid');git('config','user.name','Synthetic Check')
 (t/'f.txt').write_text('A\n');git('add','f.txt');git('commit','-qm','A')
 (t/'f.txt').write_text('B\n');git('add','f.txt');(t/'f.txt').write_text('C\n');git('commit','-qm','B')
 checks['git-index']={'committed':git('show','HEAD:f.txt'),'working':(t/'f.txt').read_text().strip(),'status':git('status','--short')}
 (t/'Makefile').write_text('app: main.o util.o\n\t@echo app\nmain.o: main.c shared.h\n\t@echo main.o\nutil.o: util.c\n\t@echo util.o\n')
 for f,stamp in [('main.c',100),('util.c',100),('shared.h',400),('main.o',200),('util.o',200),('app',300)]:
  (t/f).touch();os.utime(t/f,(stamp,stamp))
 checks['make-dependencies']={'dry_run':run(['make','-n','app'],cwd=t),'version':run(['make','--version']).splitlines()[0]}
checks['regex-fullmatch']={s:{'search':bool(re.search(r'[0-9]{2}',s)),'fullmatch':bool(re.fullmatch(r'[0-9]{2}',s))} for s in ['12','a12b','123','１２','12\n']}
a=[[1],[2]];b=a[:];b[0].append(9);c=[[4],[5]];d=c[:];d[0]=[8]
checks['python-shallow-copy']={'a_after_inner_append':a,'c_after_slot_rebind':c,'outer_distinct':a is not b,'inner_shared':a[0] is b[0]}
checks['node-event-loop']={'version':run(['node','--version']),'stdout':run(['node','--input-type=commonjs','-e','console.log("A");setTimeout(()=>console.log("B"),0);Promise.resolve().then(()=>console.log("C"));console.log("D")'])}
conn=sqlite3.connect(':memory:');conn.executescript('CREATE TABLE Students(sid INT);CREATE TABLE Enroll(sid INT,course TEXT NOT NULL);INSERT INTO Students VALUES(1),(2);INSERT INTO Enroll VALUES(1,"A"),(1,"B");')
checks['sql-left-join']={'sqlite_version':sqlite3.sqlite_version,'rows':conn.execute('SELECT s.sid,COUNT(*),COUNT(e.course) FROM Students s LEFT JOIN Enroll e ON s.sid=e.sid GROUP BY s.sid ORDER BY s.sid').fetchall()}
checks['testing-boundaries']=[{'age':x,'expected':18<=x<=65,'actual':x>18 and x<65} for x in [17,18,20,40,65,66]]
checks['debugging-hypothesis']=[{'xs':xs,'floor':sum(xs)//len(xs),'mean':sum(xs)/len(xs)} for xs in [[2.,4.],[1.,2.]]]
listeners=[];events=[]
def a_listener(v):events.append(('A',v));listeners.remove(a_listener)
def b_listener(v):events.append(('B',v))
listeners.extend([a_listener,b_listener])
for v in [1,2]:
 for listener in list(listeners):listener(v)
checks['observer-contract']={'snapshot_notification_events':events}
assert checks['node-event-loop']['stdout']=='A\nD\nC\nB'
assert checks['git-index']['committed']=='B' and checks['git-index']['working']=='C'
assert checks['sql-left-join']['rows']==[(1,2,2),(2,1,0)]
report={'schema_version':1,'kind':'bounded_reference_checks','limitations':['Concrete examples only, not universal proofs or measures of learner understanding.','No undefined C program was executed.','React state behavior is checked against official React documentation, not a local React runtime.','Runtime versions may differ from the Spark; these checks establish stated language/query cases, not server performance.'],'checks':checks,'source':Path(__file__).read_text(),'source_sha256':hashlib.sha256(Path(__file__).read_bytes()).hexdigest(),'primary_references':{'Bash redirections':'https://www.gnu.org/s/bash/manual/html_node/Redirections.html','React queued updates':'https://react.dev/learn/queueing-a-series-of-state-updates','Node event loop':'https://nodejs.org/learn/asynchronous-work/event-loop-timers-and-nexttick','UML standard':'https://www.omg.org/spec/UML/2.5.1/PDF'}}
p=Path('output/profiling/cs35l-reference-checks-v1.json');p.write_text(json.dumps(report,ensure_ascii=False,indent=2)+'\n');print('Checked12 concrete reference behaviors; retained source and results.')
